def transform_concise(grid):
    """Draw diamond paths between pairs of 2s."""
    points = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == 2]
    if not points:
        return grid

    output = [row[:] for row in grid]

    # Draw diamond of radius 2 for all points
    for r, c in points:
        for dr in range(-2, 3):
            for dc in range(-2, 3):
                if abs(dr) + abs(dc) <= 2:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < len(output) and 0 <= nc < len(output[0]):
                        if output[nr][nc] == 0:
                            output[nr][nc] = 3

    # Add midpoint 2s for horizontal pairs with even distance
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            r1, c1 = points[i]
            r2, c2 = points[j]
            if r1 == r2 and abs(c2 - c1) > 0 and abs(c2 - c1) % 2 == 0:
                output[r1][(c1 + c2) // 2] = 2

    return output

