# Let me try a different approach: diamond BETWEEN two points
def transform_between_points(grid):
    points = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == 2]
    output = [row[:] for row in grid]

    # Connect all pairs
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            r1, c1 = points[i]
            r2, c2 = points[j]

            # Check if they form a "convenient" pair
            gr = abs(r2 - r1)
            dc = abs(c2 - c1)

            # Horizontal pair with even distance
            if r1 == r2 and dc > 0 and dc % 2 == 0:
                output[r1][(c1 + c2) // 2] = 2
                # Fill between
                for c in range(min(c1, c2) + 1, max(c1, c2)):
                    if output[r1][c] == 0:
                        output[r1][c] = 3

            # Add diamond connections
            # Center at midpoint
            mr, mc = (r1 + r2) // 2, (c1 + c2) // 2

            # Draw diamond of radius depending on distance
            radius = 2 if gr + dc > 2 else 1

            for dr in range(-radius, radius + 1):
                max_dc = radius - abs(dr)
                for dc_off in range(-max_dc, max_dc + 1):
                    if output[mr + dr][mc + dc_off] == 0:
                        output[mr + dr][mc + dc_off] = 3

    return output

