# Extract just the transform function
def find_horizontal_pair(points):
    best = None
    best_dist = 0
    for i in range(len(points)):
        for j in range(i+1, len(points)):
            r1, c1 = points[i]
            r2, c2 = points[j]
            if r1 == r2 and abs(c2 - c1) >= 2:
                if abs(c2 - c1) > best_dist:
                    best_dist = abs(c2 - c1)
                    best = (r1, min(c1, c2), max(c1, c2))
    return best

def transform(grid):
    points = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == 2]
    if len(points) < 2:
        return grid

    output = [row[:] for row in grid]

    # Find the main horizontal pair
    pair = find_horizontal_pair(points)
    if pair is None:
        return output

    h_row, h_col_start, h_col_end = pair

    # Handle the horizontal pair
    dist = h_col_end - h_col_start
    if dist % 2 == 0:
        mid_col = h_col_start + dist // 2
        if output[h_row][mid_col] == 0:
            output[h_row][mid_col] = 2

    # Fill 3s between (excluding midpoint)
    for c in range(h_col_start + 1, h_col_end):
        if output[h_row][c] == 0:
            output[h_row][c] = 3
        elif output[h_row][c] == 2:
            pass

    # Connect other points vertically
    for r, c in points:
        if r != h_row:
            if r < h_row:
                for rr in range(r + 1, h_row):
                    if output[rr][c] == 0:
                        output[rr][c] = 3
            else:
                for rr in range(h_row + 1, r):
                    if output[rr][c] == 0:
                        output[rr][c] = 3

    return output

